      const candidates = [ctx.chatId, ctx.chat_id, ctx.chatID, ctx.chatFile, ctx.chatName, ctx.groupId, ctx.group_id, ctx.characterId, ctx.character_id, topWin.chat_metadata?.main_chat, topWin.chat_metadata?.chat_id, topWin.chat_metadata?.chatId, topWin.this_chid, topWin.name2];
      const hit = candidates.find(v => v !== undefined && v !== null && String(v).trim() !== '');
