  function esc(s) { return String(s==null?'':s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;'); }
  function fmtNum(n) { n=Number(n)||0; return n>=1e6?(n/1e4|0)+'w':n.toLocaleString(); }
  function randInt(a,b) { return Math.floor(Math.random()*(b-a+1))+a; }
  function sleep(ms) { return new Promise(r=>setTimeout(r,ms)); }
  function clone(o) { return JSON.parse(JSON.stringify(o)); }
  function genId() { return 'task_'+Date.now().toString(36)+'_'+randInt(100,999); }


  function setUserInputText(text) {
    const rootDoc = topWin.document || document;
    const selectors = [
      '#send_textarea',
      'textarea#send_textarea',
      'textarea[name="send_textarea"]',
      '#send_textarea textarea',
      '.mes_textarea',
      '[contenteditable="true"][role="textbox"]',
      'textarea'
    ];

    let input = null;
    for (const sel of selectors) {
      input = rootDoc.querySelector(sel);
      if (input) break;
    }

    if (!input) {
      console.warn('[adv-panel] 未找到玩家输入框，无法填入前往提示词。');
      return false;
    }

    const value = String(text || '').trim();
    const fireInput = () => {
      try {
        input.dispatchEvent(new InputEvent('input', { bubbles: true, inputType: 'insertText', data: value }));
      } catch (e) {
        input.dispatchEvent(new Event('input', { bubbles: true }));
      }
      input.dispatchEvent(new Event('change', { bubbles: true }));
    };

    input.focus();

    if (input.isContentEditable) {
      input.textContent = value;
      fireInput();
    } else {
      input.value = value;
      fireInput();
    }

    if (topWin.jQuery) topWin.jQuery(input).trigger('input').trigger('change');
    return true;
  }


  function advHashString(str) {
    let h = 2166136261;
    str = String(str || '');
    for (let i = 0; i < str.length; i++) {
      h ^= str.charCodeAt(i);
      h = Math.imul(h, 16777619);
    }
    return (h >>> 0).toString(36);
  }

