  function esc(s){ return String(s == null ? '' : s).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])); }
  function clone(v){ try { return JSON.parse(JSON.stringify(v || {})); } catch(e) { return {}; } }
  function randPick(arr){ return arr[Math.floor(Math.random() * arr.length)] || arr[0] || ''; }
  function getDB(){ return topWin.ADVENTURER_DATABASE || window.ADVENTURER_DATABASE || {}; }
  function getMvu(){ try { return topWin.Mvu || window.Mvu || null; } catch(e) { return null; } }
  function getAchievementSystem(){ try { return topWin.ADVENTURER_ACHIEVEMENT_SYSTEM || window.ADVENTURER_ACHIEVEMENT_SYSTEM || null; } catch(e) { return null; } }

  function getAdventureSettings(){
    try { return Object.assign({ preserveAdventureSave:false }, JSON.parse(topWin.localStorage.getItem(ADV_SETTINGS_KEY) || '{}')); }
    catch(e) { return { preserveAdventureSave:false }; }
  }
  function getCurrentAdventureChatId(){
    try{
      const ctx = topWin.SillyTavern?.getContext?.() || {};
      const direct = ctx.chatId || ctx.chat_id || ctx.chatID || ctx.chatFile || ctx.chatName || ctx.groupId || ctx.characterId || ctx.chat_metadata?.chat_id;
      if(direct) return String(direct);
      const meta = topWin.chat_metadata || {};
      const metaId = meta.chat_id || meta.chatId || meta.file_name || meta.name;
      if(metaId) return String(metaId);
    }catch(e){}
    try { return String(topWin.location?.pathname || 'default').replace(/[^\w.-]+/g,'_') || 'default'; } catch(e) { return 'default'; }
  }
  function getSaveKey(){ return getAdventureSettings().preserveAdventureSave ? SHARED_SAVE_KEY : `${SAVE_PREFIX}_${getCurrentAdventureChatId()}`; }
  function normalizeSave(save){
    save = save && typeof save === 'object' ? save : {};
    save.player = save.player && typeof save.player === 'object' ? save.player : {};
    save.player.inventory = save.player.inventory && typeof save.player.inventory === 'object' ? save.player.inventory : {};
    save.player.inventory_meta = save.player.inventory_meta && typeof save.player.inventory_meta === 'object' ? save.player.inventory_meta : {};
    save.player.caelian_favor_bonus = Number(save.player.caelian_favor_bonus || 0);
    save.world = save.world && typeof save.world === 'object' ? save.world : {};
    save.world.region_access = save.world.region_access && typeof save.world.region_access === 'object' ? save.world.region_access : {};
    save.achievement_stats = save.achievement_stats && typeof save.achievement_stats === 'object' ? save.achievement_stats : {};
    save.achievement_stats.interactions = save.achievement_stats.interactions && typeof save.achievement_stats.interactions === 'object' ? save.achievement_stats.interactions : {};
    save.achievement_stats.travel = save.achievement_stats.travel && typeof save.achievement_stats.travel === 'object' ? save.achievement_stats.travel : {};
    return save;
  }
  function loadSave(){
    try { return normalizeSave(JSON.parse(topWin.localStorage.getItem(getSaveKey()) || '{}')); }
    catch(e) { return normalizeSave({}); }
  }
  function writeSave(save){
    try { topWin.localStorage.setItem(getSaveKey(), JSON.stringify(normalizeSave(save))); } catch(e) {}
    try { topWin.AdventurerPanel?.refresh?.(); } catch(e) {}
    try { topWin.dispatchEvent(new CustomEvent('caelian-interaction-updated', { detail:{ source:SCRIPT_ID } })); } catch(e) {}
  }

  function unlock(id){
    if(!id) return;
    try { const sys = getAchievementSystem(); if(sys && typeof sys.unlock === 'function') sys.unlock(id); } catch(e) {}
  }
  function gameDate(save){
    try {
      const mvu = getMvu()?.getMvuData?.(MVU_OPT) || {};
      const w = mvu?.stat_data?.['世界'] || {};
      return String(w['日期'] || save?.world?.date || new Date().toISOString().slice(0,10));
    } catch(e) { return new Date().toISOString().slice(0,10); }
  }
  function ensureStats(save){
    normalizeSave(save);
    const inter = save.achievement_stats.interactions;
    ['caelian_gift_success_count','caelian_invite_success_count','caelian_gift_favor_total','trelao_pet_success_count','trelao_pet_reject_count','trelao_pet_like_streak','trelao_feed_like_count','trelao_feed_dislike_count','trelao_feed_like_streak','trelao_feed_dislike_streak','trelao_feed_bad_reaction_count'].forEach(k => inter[k] = Number(inter[k] || 0));
    inter.by_date = inter.by_date && typeof inter.by_date === 'object' ? inter.by_date : {};
    return inter;
  }
  function recordInteractionFallback(save, event){
    const inter = ensureStats(save);
    const date = gameDate(save);
    inter.by_date[date] = inter.by_date[date] && typeof inter.by_date[date] === 'object' ? inter.by_date[date] : {};
    const day = inter.by_date[date];
    const type = String(event.type || '');
    const result = String(event.result || '');
    const tags = Array.isArray(event.tags) ? event.tags.map(String) : [];
    const category = String(event.category || '');
    if(type === 'caelian_gift' && event.success !== false){
      inter.caelian_gift_success_count += 1;
      inter.caelian_gift_favor_total += Number(event.favorGain || 0.5);
      day.gift_success = true;
      unlock('ach_caelian_gift_first');
      if(inter.caelian_gift_success_count >= 10) unlock('ach_caelian_gift_10');
      if(inter.caelian_gift_success_count >= 50) unlock('ach_caelian_gift_50');
      if(inter.caelian_gift_favor_total >= 5) unlock('ach_caelian_gift_favor_5');
      if(category === 'specialty' || tags.includes('specialty')) unlock('ach_caelian_gift_specialty');
      if(tags.includes('weird_or_dirty')) unlock('ach_caelian_gift_weird');
    }
    if(type === 'caelian_invite' && event.success !== false){
      inter.caelian_invite_success_count += 1;
      day.invite_success = true;
      unlock('ach_caelian_invite_first');
      if(inter.caelian_invite_success_count >= 10) unlock('ach_caelian_invite_10');
      if(inter.caelian_invite_success_count >= 50) unlock('ach_caelian_invite_50');
      if(event.newRegion) unlock('ach_caelian_invite_new_region');
    }
    if(day.gift_success && day.invite_success) unlock('ach_caelian_social_same_day');
    if(type === 'trelao_pet'){
      if(result === 'reject'){
        inter.trelao_pet_reject_count += 1;
        inter.trelao_pet_like_streak = 0;
        unlock('ach_trelao_pet_reject_first');
      } else {
        inter.trelao_pet_success_count += 1;
        inter.trelao_pet_like_streak += 1;
        unlock('ach_trelao_pet_first');
        if(inter.trelao_pet_success_count >= 10) unlock('ach_trelao_pet_10');
        if(inter.trelao_pet_success_count >= 100) unlock('ach_trelao_pet_100');
        if(inter.trelao_pet_like_streak >= 5) unlock('ach_trelao_pet_streak_5');
      }
    }
    if(type === 'trelao_feed'){
      if(result === 'like'){
        inter.trelao_feed_like_count += 1;
        inter.trelao_feed_like_streak += 1;
        inter.trelao_feed_dislike_streak = 0;
        day.trelao_feed_like_daily_count = Number(day.trelao_feed_like_daily_count || 0) + 1;
        unlock('ach_trelao_feed_like_first');
        if(inter.trelao_feed_like_count >= 10) unlock('ach_trelao_feed_like_10');
        if(inter.trelao_feed_like_count >= 100) unlock('ach_trelao_feed_like_100');
        if(inter.trelao_feed_like_streak >= 5) unlock('ach_trelao_feed_like_streak_5');
        if(day.trelao_feed_like_daily_count >= 5) unlock('ach_trelao_feed_like_daily_5');
        if(tags.includes('meat')) unlock('ach_trelao_feed_meat_like');
        if(tags.includes('dessert')) unlock('ach_trelao_feed_dessert_like');
        if(category === 'specialty' || tags.includes('specialty')) unlock('ach_trelao_feed_specialty_like');
      }
      if(result === 'dislike'){
        inter.trelao_feed_dislike_count += 1;
        inter.trelao_feed_dislike_streak += 1;
        inter.trelao_feed_like_streak = 0;
        day.trelao_feed_dislike_daily_count = Number(day.trelao_feed_dislike_daily_count || 0) + 1;
        unlock('ach_trelao_feed_dislike_first');
        if(inter.trelao_feed_dislike_count >= 10) unlock('ach_trelao_feed_dislike_10');
        if(inter.trelao_feed_dislike_count >= 20) unlock('ach_trelao_feed_dislike_20');
        if(inter.trelao_feed_dislike_count >= 100) unlock('ach_trelao_feed_dislike_100');
        if(inter.trelao_feed_dislike_streak >= 5) unlock('ach_trelao_feed_dislike_streak_5');
        if(day.trelao_feed_dislike_daily_count >= 5) unlock('ach_trelao_feed_dislike_daily_5');
        if(tags.includes('vegetable')) unlock('ach_trelao_feed_vegetable_dislike');
        if(event.badReaction) { inter.trelao_feed_bad_reaction_count += 1; unlock('ach_trelao_feed_bad_reaction'); }
      }
    }
  }
  function recordInteraction(event){
    let usedTracker = false;
    try {
      const tracker = topWin.CaelianAchievementTracker || window.CaelianAchievementTracker;
      if(tracker && typeof tracker.recordInteraction === 'function') { tracker.recordInteraction(event || {}); usedTracker = true; }
    } catch(e) {}
    const save = loadSave();
    if(!usedTracker) recordInteractionFallback(save, event || {});
    return save;
  }

  async function addCaelianFavor(delta){
    const n = Number(delta || 0);
    if(!Number.isFinite(n) || !n) return;
    try {
      const m = getMvu();
      if(m && typeof m.getMvuData === 'function' && typeof m.replaceMvuData === 'function'){
        const data = clone(m.getMvuData(MVU_OPT) || {});
        data.stat_data = data.stat_data && typeof data.stat_data === 'object' ? data.stat_data : {};
        data.stat_data['凯利安'] = data.stat_data['凯利安'] && typeof data.stat_data['凯利安'] === 'object' ? data.stat_data['凯利安'] : {};
        const cur = Number(data.stat_data['凯利安']['好感度'] || 0);
        data.stat_data['凯利安']['好感度'] = Math.max(0, Math.min(100, cur + n));
        await m.replaceMvuData(data, MVU_OPT);
      }
    } catch(e) {}
  }

  function priceOf(name){
    const DB = getDB();
    const p = DB.ITEM_PRICE_DB && DB.ITEM_PRICE_DB[name];
    if(Number(p) > 0) return Number(p);
    let found = 0;
    function scan(v){
      if(found) return;
      if(Array.isArray(v)) v.forEach(scan);
      else if(v && typeof v === 'object'){
        const nm = v.name || v.名称 || v.item || v.itemName;
        if(String(nm || '') === String(name)) found = Number(v.price || v.sell || v.value || 0) || 0;
        Object.values(v).forEach(scan);
      }
    }
    try { scan(DB.MARKET_ITEMS); } catch(e) {}
    return found;
  }
  function inventoryEntries(save){
    const inv = normalizeSave(save).player.inventory;
    return Object.entries(inv).map(([name,count]) => ({ name, count:Number(count || 0) })).filter(x => x.count > 0);
  }
  function itemTags(name){
    const s = String(name || '');
    const tags = [];
    if(GIFT_SPECIALTY.has(s)) tags.push('specialty');
    if(/肉|鸡|火腿|烤|鱼|海胆|海鲜|狼皮|毛皮/.test(s)) tags.push('meat');
    if(/糖|甜|蛋糕|蜂蜜|饼干|浆果|灵感糖丸/.test(s)) tags.push('dessert');
    if(/西蓝花|草|苔|百合|薄荷|树脂|新芽|纤维|花|藤蔓|药草/.test(s)) tags.push('vegetable');
    if(/肮脏|腐烂|烂牙|碎骨|鼠尾|黑市|旧墓|血浆|机油|残片|毒|尸|哥布林|粘液|灰|粉尘/.test(s)) tags.push('weird_or_dirty');
    if(getDB().BATTLE_ITEM_DB && getDB().BATTLE_ITEM_DB[s]) tags.push('consumable');
    return [...new Set(tags)];
  }
  function giftCategory(name){ return itemTags(name).includes('specialty') ? 'specialty' : 'sellable'; }
  function giftItems(save){
    return inventoryEntries(save)
      .filter(x => priceOf(x.name) > 0)
      .map(x => ({ ...x, price:priceOf(x.name), tags:itemTags(x.name), category:giftCategory(x.name) }))
      .sort((a,b) => a.name.localeCompare(b.name,'zh-Hans-CN'));
  }
  function feedMeta(name){
    const tags = itemTags(name);
    const DB = getDB();
    const isConsumable = !!(DB.BATTLE_ITEM_DB && DB.BATTLE_ITEM_DB[name]);
    const isSpecialty = tags.includes('specialty');
    const foodLike = FEED_LIKE_EXPLICIT.has(name) || tags.includes('meat') || tags.includes('dessert');
    const foodDislike = FEED_DISLIKE_EXPLICIT.has(name) || tags.includes('vegetable') || tags.includes('weird_or_dirty') || (/药水|药瓶|秘药|药剂|卷轴|粉尘|灰/.test(String(name)));
    let result = 'dislike';
    if(foodLike && !FEED_DISLIKE_EXPLICIT.has(name)) result = 'like';
    if(foodDislike) result = 'dislike';
    const category = isSpecialty ? 'specialty' : (isConsumable ? 'consumable' : 'feedable');
    const allowed = FEED_LIKE_EXPLICIT.has(name) || FEED_DISLIKE_EXPLICIT.has(name) || isConsumable || isSpecialty || /肉|鸡|火腿|鱼|海胆|面包|便当|糖|蛋糕|甜|蜂蜜|饼干|酒|血浆|机油|西蓝花|草|苔|百合|薄荷/.test(String(name));
    return { allowed, result, tags, category, source: isConsumable ? '消耗品' : (isSpecialty ? '地区特产/集市物品' : '可投喂物品') };
  }
  function feedItems(save){
    return inventoryEntries(save)
      .map(x => ({ ...x, meta:feedMeta(x.name) }))
      .filter(x => x.meta.allowed)
      .sort((a,b) => (a.meta.result === b.meta.result ? a.name.localeCompare(b.name,'zh-Hans-CN') : (a.meta.result === 'like' ? -1 : 1)));
  }

  function consumeItem(save, name, count=1){
    normalizeSave(save);
    const c = Number(save.player.inventory[name] || 0);
    if(c < count) return false;
    const next = c - count;
    if(next > 0) save.player.inventory[name] = next;
    else delete save.player.inventory[name];
    return true;
  }

  function setUserInputText(text){
    const rootDoc = topWin.document || document;
    const selectors = ['#send_textarea','textarea#send_textarea','textarea[name="send_textarea"]','#send_textarea textarea','#send_form textarea','.mes_textarea','textarea[placeholder*="输入"]','textarea[placeholder*="消息"]','[contenteditable="true"][role="textbox"]','[contenteditable="true"]','textarea'];
    let input = null;
    for(const sel of selectors){ try { input = rootDoc.querySelector(sel); if(input) break; } catch(e) {} }
    if(!input) return false;
    const value = String(text || '').trim();
    input.focus();
    if(input.isContentEditable) input.textContent = value;
    else input.value = value;
    try { input.dispatchEvent(new InputEvent('input',{ bubbles:true, inputType:'insertText', data:value })); } catch(e) { input.dispatchEvent(new Event('input',{ bubbles:true })); }
    input.dispatchEvent(new Event('change',{ bubbles:true }));
    try { if(topWin.jQuery) topWin.jQuery(input).trigger('input').trigger('change'); } catch(e) {}
    return true;
  }

